/**
 * @file src/app/manifest.ts
 * @description Web App Manifest — makes Cervos installable on Android, iOS
 * (via Add to Home Screen) and desktop.
 *
 * Next.js serves this file convention at `/manifest.webmanifest` and injects
 * the matching `<link rel="manifest">` automatically, so the root layout does
 * NOT declare that link by hand.
 *
 * iOS does not read this file — it relies on `apple-touch-icon` +
 * `appleWebApp` metadata in `src/app/layout.tsx`. Both are required for the
 * iPhone "Add to Home Screen" experience.
 *
 * Icon files are generated by `scripts/generate-pwa-icons.mjs`.
 */
import type { MetadataRoute } from "next";

export default function manifest(): MetadataRoute.Manifest {
  return {
    id: "/",
    name: "Cervos Pharma",
    short_name: "Cervos Pharma",
    description:
      "Precision logistics for the modern pharmacy. Secure, offline-first, FEFO-optimised.",
    start_url: "/",
    scope: "/",
    display: "standalone",
    // Falls back to a browser UI rather than a bare document if the OS
    // decides standalone is inappropriate (e.g. a desktop pointer device).
    display_override: ["standalone", "minimal-ui", "browser"],
    // Shown as the splash background while the first paint is pending, so it
    // must match the app's own background (`bg-surface`) or the transition
    // flashes white.
    background_color: "#fcf8ff",
    theme_color: "#1039b9",
    lang: "en",
    dir: "ltr",
    categories: ["business", "productivity", "medical"],
    icons: [
      { src: "/icon-192x192.png", sizes: "192x192", type: "image/png" },
      { src: "/icon-512x512.png", sizes: "512x512", type: "image/png" },
      {
        src: "/icon-maskable-512.png",
        sizes: "512x512",
        type: "image/png",
        // `purpose: "maskable"` tells Android the icon may be clipped by the
        // adaptive-icon mask, so it must use the pre-padded (80% inset) art.
        // Without this entry Android stretches the unpadded 512 icon instead.
        purpose: "maskable",
      },
      // `any` as well, so browsers that ignore `maskable` still get a
      // correctly-proportioned 512 icon rather than nothing.
      { src: "/icon-512x512.png", sizes: "512x512", type: "image/png", purpose: "any" },
    ],
  };
}
